<?php
namespace App\Livewire\Admin\CallCentre;use App\Models\CallCenterCall;use Livewire\Attributes\Url;use Livewire\Component;use Livewire\WithPagination;
class Index extends Component{use WithPagination;#[Url]public string $status='';#[Url]public string $type='';#[Url]public string $search='';public function mount():void{abort_unless(auth()->user()->isAdmin()||auth()->user()->isCallCenter(),403);}public function render(){$u=auth()->user();$q=CallCenterCall::query()->with(['lead','assignedUser'])->when(!$u->isAdmin(),fn($q)=>$q->where('assigned_call_center_user',$u->id))->when($this->status,fn($q)=>$q->where('status',$this->status))->when($this->type,fn($q)=>$q->where('call_type',$this->type))->when($this->search,fn($q)=>$q->whereHas('lead',fn($q)=>$q->where('customer_name','like','%'.$this->search.'%')));return view('livewire.admin.call-centre.index',['calls'=>$q->latest()->paginate(25),'statuses'=>CallCenterCall::getStatuses(),'types'=>CallCenterCall::getCallTypes()])->layout('components.layouts.admin',['title'=>'Call centre']);}}
